// Parse payload: čita form-urlencoded polje `payload` (JSON), priprema Meta CAPI body,
// PostHog HogQL upit i tekstove mailova. Vraća [] (= stop) za neispravan ulaz.
const crypto = require('crypto');
const cfg = $('Config').first().json;
const req = $('Webhook ursa-capi').first().json;
const headers = req.headers || {};
const body = req.body || {};

let p = null;
try {
  if (typeof body.payload === 'string') p = JSON.parse(body.payload);
  else if (body.payload && typeof body.payload === 'object') p = body.payload;
  else if (typeof body.event_name === 'string') p = body;
} catch (e) {
  p = null;
}
if (!p || typeof p !== 'object' || Array.isArray(p)) return [];

const ALLOWED_EVENTS = ['Lead', 'InitiateCheckout'];
const eventName = p.event_name;
const eventId = p.event_id; // Meta dedup ključ s pixelom: ne dirati
if (!ALLOWED_EVENTS.includes(eventName)) return [];
if (typeof eventId !== 'string' || !eventId || eventId.length > 200) return [];

const str = (v, max = 500) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v) ? v : {});
const sha256 = (s) => crypto.createHash('sha256').update(s, 'utf8').digest('hex');
const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const now = Math.floor(Date.now() / 1000);
let eventTime = Number(p.event_time);
if (eventTime > 1e12) eventTime = eventTime / 1000; // ms -> s
eventTime = Math.floor(eventTime);
if (!Number.isFinite(eventTime) || eventTime < now - 7 * 86400) eventTime = now;
if (eventTime > now) eventTime = now; // Meta odbija evente iz budućnosti

const email = str(p.email, 254).toLowerCase();
// Strogo: samo "obični" emailovi, bez navodnika, razmaka i backslasha.
const EMAIL_RE = /^[a-z0-9._%+-]+@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,24}$/;
const emailOk = EMAIL_RE.test(email);
const firstName = str(p.first_name, 60);
// Mobitel iz kviza (neobavezno): znamenke s pozivnim brojem, npr. 385912345678
const phoneDigits = String(p.phone || '').replace(/\D/g, '');
const phone = phoneDigits.length >= 8 && phoneDigits.length <= 15 ? phoneDigits : '';
const quiz = obj(p.quiz);
const attribution = obj(p.attribution);

// ---------- Meta CAPI ----------
const xff = String(headers['x-forwarded-for'] || '');
const ipRaw = xff.split(',')[0].trim();
const ip = /^[0-9a-fA-F:.]{3,45}$/.test(ipRaw) ? ipRaw : '';
const userAgent = str(p.user_agent, 1000) || str(headers['user-agent'], 1000);
const fbp = str(p.fbp, 300);
const fbc = str(p.fbc, 500);

const userData = {};
if (emailOk) {
  userData.em = [sha256(email)];
  userData.external_id = [sha256(email)];
}
if (firstName) userData.fn = [sha256(firstName.toLowerCase())];
if (phone) userData.ph = [sha256(phone)];
if (ip) userData.client_ip_address = ip;
if (userAgent) userData.client_user_agent = userAgent;
if (fbp) userData.fbp = fbp;
if (fbc) userData.fbc = fbc;

const capiEvent = {
  event_name: eventName,
  event_id: eventId,
  event_time: eventTime,
  action_source: 'website',
  user_data: userData,
};
const sourceUrl = str(p.event_source_url, 2000);
if (sourceUrl) capiEvent.event_source_url = sourceUrl;
if (p.custom_data && typeof p.custom_data === 'object') capiEvent.custom_data = p.custom_data;

const capiBody = { data: [capiEvent] };
const testCode = str(cfg.META_TEST_EVENT_CODE, 100);
if (testCode) capiBody.test_event_code = testCode;

const pixelId = String(cfg.META_PIXEL_ID || '').trim();
const apiVersion = String(cfg.META_API_VERSION || 'v26.0').trim();
const capiReady = /^\d{5,25}$/.test(pixelId) && /^v\d+\.\d+$/.test(apiVersion);
const capiUrl = `https://graph.facebook.com/${apiVersion}/${pixelId}/events`;

// ---------- Koji follow-up ----------
const phProject = String(cfg.POSTHOG_PROJECT_ID || '').trim();
const phHost = String(cfg.POSTHOG_HOST || 'https://eu.posthog.com').trim().replace(/\/+$/, '');
const stopList = String(cfg.STOP_EMAILS || '').toLowerCase().split(/[\s,;]+/).filter(Boolean);

let flow = 'none';
let skipReason = '';
if (!emailOk) skipReason = 'no_valid_email';
else if (stopList.includes(email)) skipReason = 'stop_list';
else if (!/^\d+$/.test(phProject)) skipReason = 'posthog_not_configured';
else flow = eventName === 'Lead' ? 'lead' : 'checkout';

// Isti email + isti tok unutar 48 h -> bez druge sekvence (CAPI ide svejedno).
// Static data se pamti samo u produkcijskim (aktivnim) izvršenjima.
if (flow !== 'none') {
  const sd = $getWorkflowStaticData('global');
  const seen = (sd.seen && typeof sd.seen === 'object') ? sd.seen : {};
  for (const k of Object.keys(seen)) if (now - seen[k] > 3 * 86400) delete seen[k];
  const key = flow + ':' + email;
  if (seen[key] && now - seen[key] < 2 * 86400) {
    skipReason = 'duplicate_48h';
    flow = 'none';
  } else {
    seen[key] = now;
  }
  sd.seen = seen;
}

// ---------- PostHog provjera ----------
// Vrijednosti idu kroz HogQL placeholdere ("values"), email je uz to strogo validiran.
const since = eventTime - 15 * 60; // 15 min tolerancije za sat preglednika
const hogql = [
  'SELECT',
  "  countIf(event = 'quiz_completed') AS quiz_completed,",
  "  countIf(event = 'vsl_viewed') AS vsl_viewed,",
  "  countIf(event = 'vsl_50') AS vsl_50,",
  "  countIf(event = 'vsl_checkout_clicked') AS vsl_checkout_clicked,",
  "  countIf(event = 'purchase') AS purchase",
  'FROM events',
  "WHERE event IN ('quiz_completed', 'vsl_viewed', 'vsl_50', 'vsl_checkout_clicked', 'purchase')",
  '  AND timestamp >= now() - INTERVAL 4 DAY',
  '  AND toUnixTimestamp(timestamp) >= {since}',
  '  AND (',
  '    person_id IN (SELECT id FROM persons WHERE properties.email = {email})',
  '    OR person_id IN (SELECT person_id FROM person_distinct_ids WHERE distinct_id = {email})',
  '  )',
].join('\n');
const hogqlBody = {
  query: { kind: 'HogQLQuery', query: hogql, values: { email, since } },
  refresh: 'force_blocking',
  name: 'ursa_abandon_check',
};
const posthogQueryUrl = `${phHost}/api/projects/${phProject}/query/`;

// ---------- Mailovi ----------
const gender = str(quiz.gender, 20).toLowerCase();
const female = gender.startsWith('ž') || gender.startsWith('z'); // 'Žensko'
const g = (m, f) => (female ? f : m);
const name = firstName ? firstName.charAt(0).toUpperCase() + firstName.slice(1) : '';
const hej = name ? `Hej ${name},` : 'Hej,';
const goal = str(quiz.goal, 200);
const OPT_OUT = 'Ako ne želiš ovakve poruke, samo odgovori STOP.';
// Ursin broj (Config URSA_PHONE): poziv ili WhatsApp, u svakom mailu prije potpisa
const ursaPhone = str(cfg.URSA_PHONE, 40);
const ursaWa = ursaPhone.replace(/\D/g, '');
const contactBlocks = ursaWa.length >= 8
  ? [`Ako ti je lakše razgovarati, nazovi me ili mi piši na WhatsApp: ${ursaPhone}`, { link: `https://wa.me/${ursaWa}`, label: 'Piši mi na WhatsApp' }]
  : [];
const emailFrom = str(cfg.EMAIL_FROM, 200) || 'Ursa <ursa@nemaneide.com>';
const fromAddr = (emailFrom.match(/<([^>]+)>/) || [null, emailFrom])[1];

function withUtm(url, campaign) {
  const [beforeHash, hash] = url.split('#');
  const [base, qs] = beforeHash.split('?');
  const drop = ['utm_source', 'utm_medium', 'utm_campaign'];
  const parts = (qs || '').split('&').filter((kv) => kv && !drop.includes(kv.split('=')[0]));
  parts.push('utm_source=email', 'utm_medium=abandon', 'utm_campaign=' + encodeURIComponent(campaign));
  return base + '?' + parts.join('&') + (hash !== undefined ? '#' + hash : '');
}
const SAFE_URL = /^https:\/\/([a-z0-9-]+\.)*ursaprotocol\.com(\/[^\s"'<>\\]*)?$/i;

function vslLink() {
  let url = str(p.vsl_url, 2000);
  if (!SAFE_URL.test(url)) {
    const q = [];
    if (firstName) q.push('name=' + encodeURIComponent(firstName));
    for (const k of ['goal', 'gender', 'bodytype']) {
      if (str(quiz[k])) q.push(k + '=' + encodeURIComponent(str(quiz[k])));
    }
    url = 'https://ursaprotocol.com/vsl.html' + (q.length ? '?' + q.join('&') : '');
  }
  return withUtm(url, 'quiz_no_vsl');
}

// blocks: string = odlomak, {link, label} = link u svom redu
function compose(subject, blocks, tag) {
  const html = '<div style="font-family:Arial,sans-serif;font-size:15px;line-height:1.6;color:#1F2937;max-width:560px;">'
    + blocks.map((b) => (typeof b === 'string'
      ? `<p>${esc(b)}</p>`
      : `<p><a href="${esc(b.link)}" style="color:#1F2937;font-weight:bold;">${esc(b.label)}</a></p>`)).join('')
    + `<p style="color:#6B7280;font-size:13px;margin-top:24px;">${esc(OPT_OUT)}</p></div>`;
  const text = blocks.map((b) => (typeof b === 'string' ? b : `${b.label}: ${b.link}`)).join('\n\n')
    + '\n\n' + OPT_OUT;
  return {
    idempotency_key: `${eventId}:${tag}`.slice(0, 256),
    request: {
      from: emailFrom,
      to: [email],
      subject,
      html,
      text,
      headers: { 'List-Unsubscribe': `<mailto:${fromAddr}?subject=STOP>` },
    },
  };
}

const mail = {};
if (flow === 'lead') {
  mail.vsl = compose(
    name ? `${name}, jesi ${g('stigao', 'stigla')} pogledati?` : `Jesi ${g('stigao', 'stigla')} pogledati?`,
    [
      hej,
      `jesi ${g('stigao', 'stigla')} pogledati plan koji ti je izašao na kraju kviza? Složen je prema onome što si ${g('odgovorio', 'odgovorila')}, pa ga vrijedi pogledati dok su ti odgovori još svježi.`,
      { link: vslLink(), label: 'Otvori svoj plan' },
      'Ako ti nešto nije bilo jasno, pitaj slobodno. Samo odgovori na ovaj mail.',
      ...contactBlocks,
      '— Ursa',
    ],
    'lead_vsl',
  );
  mail.goal = compose(
    name ? `${name}, jedno pitanje` : 'Jedno pitanje',
    [
      hej,
      goal
        ? `u kvizu si kao cilj ${g('označio', 'označila')}: ${goal}. Imam samo jedno pitanje: što te trenutno najviše koči da do toga dođeš?`
        : 'imam samo jedno pitanje: što te trenutno najviše koči da dođeš do forme kakvu želiš?',
      'Dovoljna je jedna ili dvije rečenice, samo odgovori na ovaj mail. Iz toga ću ti moći reći odakle bih ja krenuo na tvom mjestu.',
      ...contactBlocks,
      '— Ursa',
    ],
    'lead_goal',
  );
} else if (flow === 'checkout') {
  const back = SAFE_URL.test(sourceUrl) ? withUtm(sourceUrl, 'checkout_24h') : '';
  mail.ic1 = compose(
    name ? `${name}, imaš li kakvo pitanje?` : 'Imaš li kakvo pitanje?',
    [
      hej,
      'ako ti je oko programa ostalo kakvo pitanje, koliko vremena traži, kako izgleda trening ili što s prehranom, slobodno mi napiši.',
      'Samo odgovori na ovaj mail. Lakše je to razjasniti u dvije poruke nego nagađati.',
      ...contactBlocks,
      '— Ursa',
    ],
    'checkout_1',
  );
  mail.ic2 = compose(
    name ? `${name}, još samo ovo` : 'Još samo ovo',
    [
      hej,
      'javljam se još jednom i onda te ne gnjavim.',
      'Ako sad nije pravo vrijeme, potpuno razumijem. A ako je nešto drugo u pitanju, nešto ti nije jasno, imaš ozljedu, radiš u smjenama ili ne znaš je li ovo za tebe, napiši mi u jednoj rečenici pa ćemo vidjeti ima li smisla.',
      ...(back ? [{ link: back, label: 'Plan ti je i dalje ovdje' }] : []),
      ...contactBlocks,
      '— Ursa',
    ],
    'checkout_2',
  );
}

return [{
  json: {
    event_name: eventName,
    event_id: eventId,
    event_time: eventTime,
    flow,
    skip_reason: skipReason,
    email: emailOk ? email : '',
    first_name: firstName,
    gender: str(quiz.gender, 20),
    goal,
    bodytype: str(quiz.bodytype, 100),
    utm_content: str(attribution.utm_content, 200),
    phone: phone ? '+' + phone : '',
    age: str(quiz.age, 50),
    motivation: str(quiz.motivation, 200),
    struggle: str(quiz.struggle, 200),
    tried: str(quiz.tried, 200),
    diet: str(quiz.diet, 200),
    fear: str(quiz.fear, 200),
    plan: str(obj(p.custom_data).content_name, 50),
    value: Number(obj(p.custom_data).value) || 0,
    capi_ready: capiReady,
    capi_url: capiUrl,
    capi_body: capiBody,
    posthog_query_url: posthogQueryUrl,
    hogql_body: hogqlBody,
    mail,
  },
}];

// Lead, 1 h nakon kviza
const p = $('Parse payload').first().json;
const res = $input.first().json || {};
const cols = Array.isArray(res.columns) ? res.columns : [];
const row = Array.isArray(res.results) && Array.isArray(res.results[0]) ? res.results[0] : null;
if (!row || !cols.length) {
  // Bez pouzdanog odgovora ne šaljemo ništa (da ne pišemo nekome tko je već kupio).
  throw new Error('PostHog upit nije vratio rezultat: ' + JSON.stringify(res).slice(0, 400));
}
const c = {};
cols.forEach((k, i) => { c[k] = Number(row[i]) || 0; });

let decision;
if (!c.quiz_completed) decision = 'stop_unverified'; // email nije prošao quiz (zaštita javnog webhooka)
else if (c.vsl_checkout_clicked || c.purchase) decision = 'stop_converted';
else if (!c.vsl_viewed) decision = 'send_vsl_link';
else decision = 'wait';

return [{ json: { check: '1h', decision, counts: c, email: p.email } }];

// Lead, 24 h nakon kviza
const p = $('Parse payload').first().json;
const res = $input.first().json || {};
const cols = Array.isArray(res.columns) ? res.columns : [];
const row = Array.isArray(res.results) && Array.isArray(res.results[0]) ? res.results[0] : null;
if (!row || !cols.length) {
  // Bez pouzdanog odgovora ne šaljemo ništa (da ne pišemo nekome tko je već kupio).
  throw new Error('PostHog upit nije vratio rezultat: ' + JSON.stringify(res).slice(0, 400));
}
const c = {};
cols.forEach((k, i) => { c[k] = Number(row[i]) || 0; });

let decision;
if (!c.quiz_completed) decision = 'stop_unverified';
else if (c.vsl_checkout_clicked || c.purchase) decision = 'stop_converted';
else if (c.vsl_50) decision = 'slack';
else if (c.vsl_viewed) decision = 'ask_goal';
else decision = 'stop_no_vsl'; // mail s linkom je već otišao na 1 h, drugi ne šaljemo

const dash = (v) => (v ? String(v) : '—');
const f = /^(ž|z)/i.test(String(p.gender || ''));
const cfgPh = $('Config').first().json;
const personUrl = `https://eu.posthog.com/project/${cfgPh.POSTHOG_PROJECT_ID}/person/${encodeURIComponent(p.email)}`;
const slackText = [
  `:fire: *${dash(p.first_name)}* je ${f ? 'odgledala' : 'odgledao'} više od pola VSL-a i nije ${f ? 'otišla' : 'otišao'} na checkout (24 h nakon kviza)`,
  `*Mobitel:* ${p.phone ? p.phone : (f ? 'nije ostavila' : 'nije ostavio')}`,
  `*Email:* ${p.email}`,
  `*Spol:* ${dash(p.gender)} | *Dob:* ${dash(p.age)} | *Tip tijela:* ${dash(p.bodytype)}`,
  `*Cilj:* ${dash(p.goal)}`,
  `*Motivacija:* ${dash(p.motivation)}`,
  `*Najveći problem:* ${dash(p.struggle)}`,
  `*Što je probao/la:* ${dash(p.tried)}`,
  `*Prehrana:* ${dash(p.diet)}`,
  `*Strah:* ${dash(p.fear)}`,
  `*Oglas:* ${dash(p.utm_content)}`,
  `*PostHog:* ${personUrl}`,
  'Automatski mail nije poslan. *Javi se ručno:* poziv ili WhatsApp ako ima broj, inače mail.',
].join('\n');

return [{ json: { check: '24h', decision, counts: c, email: p.email, slack_text: slackText } }];

// InitiateCheckout, 1h nakon klika
const p = $('Parse payload').first().json;
const res = $input.first().json || {};
const cols = Array.isArray(res.columns) ? res.columns : [];
const row = Array.isArray(res.results) && Array.isArray(res.results[0]) ? res.results[0] : null;
if (!row || !cols.length) {
  // Bez pouzdanog odgovora ne šaljemo ništa (da ne pišemo nekome tko je već kupio).
  throw new Error('PostHog upit nije vratio rezultat: ' + JSON.stringify(res).slice(0, 400));
}
const c = {};
cols.forEach((k, i) => { c[k] = Number(row[i]) || 0; });

let decision;
if (!c.vsl_checkout_clicked) decision = 'stop_unverified'; // nema klika u PostHogu za taj email
else if (c.purchase) decision = 'stop_converted';
else decision = 'send';

const dash = (v) => (v ? String(v) : '—');
const cfgPh = $('Config').first().json;
const personUrl = `https://eu.posthog.com/project/${cfgPh.POSTHOG_PROJECT_ID}/person/${encodeURIComponent(p.email)}`;
const slackText = [
  `:shopping_trolley: *${dash(p.first_name)}* je kliknuo/la checkout prije 1 h i nije platio/la`,
  `*Mobitel:* ${p.phone ? p.phone : 'nije ostavio/la'}`,
  `*Email:* ${p.email}`,
  `*Paket:* ${dash(p.plan)}${p.value ? ' (' + p.value + ' €)' : ''}`,
  `*Oglas:* ${dash(p.utm_content)}`,
  `*PostHog:* ${personUrl}`,
  'Mail "Imaš li kakvo pitanje?" je upravo poslan. Ako ima broj, *nazovi*.',
].join('\n');

return [{ json: { check: '1h', decision, counts: c, email: p.email, slack_text: slackText } }];

// InitiateCheckout, 24h nakon klika
const p = $('Parse payload').first().json;
const res = $input.first().json || {};
const cols = Array.isArray(res.columns) ? res.columns : [];
const row = Array.isArray(res.results) && Array.isArray(res.results[0]) ? res.results[0] : null;
if (!row || !cols.length) {
  // Bez pouzdanog odgovora ne šaljemo ništa (da ne pišemo nekome tko je već kupio).
  throw new Error('PostHog upit nije vratio rezultat: ' + JSON.stringify(res).slice(0, 400));
}
const c = {};
cols.forEach((k, i) => { c[k] = Number(row[i]) || 0; });

let decision;
if (!c.vsl_checkout_clicked) decision = 'stop_unverified'; // nema klika u PostHogu za taj email
else if (c.purchase) decision = 'stop_converted';
else decision = 'send';

return [{ json: { check: '24h', decision, counts: c, email: p.email } }];
